{
  "name": "Yoctopuce SPI通信接口模块",
  "name_en": "Yoctopuce SPI Communication Interface Module",
  "manufacturer": "Yoctopuce",
  "description": "用于实验系统中连接和控制 SPI 外设的硬件接口模块，可配置串行协议、SPI 模式、位序、片选线极性与电平，并发送、接收和查询文本或二进制数据。",
  "description_en": "A hardware SPI interface module for connecting and controlling SPI peripherals in laboratory setups. It can configure the serial protocol, SPI mode, bit order, chip-select polarity, and line voltage, and can send, receive, and query text or binary data.",
  "actions": [
    {
      "action_name": "auto-set_currentJob",
      "description": "设置当前作业文件",
      "description_en": "Set the current job file."
    },
    {
      "action_name": "auto-set_startupJob",
      "description": "设置上电启动作业文件",
      "description_en": "Set the startup job file."
    },
    {
      "action_name": "auto-set_command",
      "description": "设置命令字符串",
      "description_en": "Set the command string."
    },
    {
      "action_name": "auto-set_protocol",
      "description": "设置串行协议类型",
      "description_en": "Set the serial protocol type."
    },
    {
      "action_name": "auto-set_voltageLevel",
      "description": "设置串行线电压电平",
      "description_en": "Set the serial line voltage level."
    },
    {
      "action_name": "auto-set_spiMode",
      "description": "设置SPI通信模式参数",
      "description_en": "Set the SPI communication mode parameters."
    },
    {
      "action_name": "auto-set_ssPolarity",
      "description": "设置SS片选线极性",
      "description_en": "Set the SS chip-select line polarity."
    },
    {
      "action_name": "auto-set_shiftSampling",
      "description": "设置SDI采样相位偏移",
      "description_en": "Set the SDI sampling phase shift."
    },
    {
      "action_name": "auto-sendCommand",
      "description": "向SPI端口发送命令",
      "description_en": "Send a command to the SPI port."
    },
    {
      "action_name": "auto-readLine",
      "description": "从接收缓冲区读取一条文本行或消息",
      "description_en": "Read one text line or message from the receive buffer."
    },
    {
      "action_name": "auto-readMessages",
      "description": "读取与模式匹配的接收消息",
      "description_en": "Read received messages matching a pattern."
    },
    {
      "action_name": "auto-read_seek",
      "description": "设置读取流的当前位置",
      "description_en": "Set the current read stream position."
    },
    {
      "action_name": "auto-read_tell",
      "description": "获取当前读取流位置",
      "description_en": "Get the current read stream position."
    },
    {
      "action_name": "auto-read_avail",
      "description": "获取当前位置可读取的字节数",
      "description_en": "Get the number of bytes available to read from the current position."
    },
    {
      "action_name": "auto-queryLine",
      "description": "发送文本行查询并读取回复",
      "description_en": "Send a line-based query and read the reply."
    },
    {
      "action_name": "auto-queryHex",
      "description": "发送二进制十六进制查询并读取回复",
      "description_en": "Send a binary hexadecimal query and read the reply."
    },
    {
      "action_name": "auto-uploadJob",
      "description": "上传JSON作业定义文件到设备",
      "description_en": "Upload a JSON job definition file to the device."
    },
    {
      "action_name": "auto-selectJob",
      "description": "加载并启动指定作业文件",
      "description_en": "Load and start the specified job file."
    },
    {
      "action_name": "auto-reset",
      "description": "清空端口缓冲区并复位计数器",
      "description_en": "Clear the port buffers and reset counters."
    },
    {
      "action_name": "auto-writeByte",
      "description": "写入单个字节",
      "description_en": "Write a single byte."
    },
    {
      "action_name": "auto-writeStr",
      "description": "写入ASCII字符串",
      "description_en": "Write an ASCII string."
    },
    {
      "action_name": "auto-writeBin",
      "description": "写入二进制缓冲区",
      "description_en": "Write a binary buffer."
    },
    {
      "action_name": "auto-writeArray",
      "description": "写入字节数组",
      "description_en": "Write a byte array."
    },
    {
      "action_name": "auto-writeHex",
      "description": "写入十六进制字节序列",
      "description_en": "Write a hexadecimal byte sequence."
    },
    {
      "action_name": "auto-writeLine",
      "description": "写入带换行的ASCII文本行",
      "description_en": "Write an ASCII line with a line break."
    },
    {
      "action_name": "auto-readByte",
      "description": "读取单个字节",
      "description_en": "Read a single byte."
    },
    {
      "action_name": "auto-readStr",
      "description": "读取字符串数据",
      "description_en": "Read data as a string."
    },
    {
      "action_name": "auto-readBin",
      "description": "读取二进制数据",
      "description_en": "Read binary data."
    },
    {
      "action_name": "auto-readArray",
      "description": "读取字节数组数据",
      "description_en": "Read data as a byte array."
    },
    {
      "action_name": "auto-readHex",
      "description": "读取十六进制字符串数据",
      "description_en": "Read data as a hexadecimal string."
    },
    {
      "action_name": "auto-set_SS",
      "description": "手动设置SS片选线状态",
      "description_en": "Manually set the SS chip-select line state."
    },
    {
      "action_name": "auto-nextSpiPort",
      "description": "枚举下一个可访问的SPI端口",
      "description_en": "Enumerate the next accessible SPI port."
    }
  ],
  "tag_hints": [
    "SPI communication",
    "Yoctopuce",
    "serial peripheral interface",
    "chip select control",
    "logic level selection",
    "binary and text data transfer",
    "lab hardware interface"
  ]
}

